        // 无引号属性（src=cid:xxx>）会把 > 带进捕获组，剥掉尾随尖括号
        if (s.length() > 1 && s.endsWith(">") && !s.startsWith("<")) {
            s = s.substring(0, s.length() - 1);
        }
        return s.trim().toLowerCase(Locale.ROOT);
    }

