    private int countTotalParts(jakarta.mail.Part root) {
        Deque<jakarta.mail.Part> parts = new ArrayDeque<>();
        Deque<Integer> depths = new ArrayDeque<>();
        parts.push(root);
        depths.push(0);
        int count = 0;
        while (!parts.isEmpty()) {
            jakarta.mail.Part part = parts.pop();
            int depth = depths.pop();
